import json, pandas as pd, numpy as np
O = "out/"
R = json.load(open(O + "pd_results.json")); V = json.load(open(O + "verify_pd.json"))
MC = pd.read_csv(O + "model_comparison.csv"); LV = pd.read_csv(O + "label_variants_cv.csv")
D12 = pd.read_csv(O + "calibration_deciles_2023_12m.csv"); LT = pd.read_csv(O + "levels_train_oof.csv")
L12 = pd.read_csv(O + "levels_2023_12m.csv"); L21 = pd.read_csv(O + "levels_2023_21m.csv")
def n(x, d=2): return f"{x:.{d}f}".replace(".", ",")
def pc(x, d=1): return n(x * 100, d) + "%"
def k(x): return f"{int(x):,}".replace(",", " ")
t12, t21, tr = R["test_12m"], R["test_21m"], R["train"]
au = R["leakage_audit"]; bt = au["gini_by_default_type"]
lg = MC[MC.model == "LightGBM"].iloc[0]; lr_l = MC[MC.model == "LogReg linear"].iloc[0]; lr_s = MC[MC.model == "LogReg splines"].iloc[0]; cb = MC[MC.model == "CatBoost"].iloc[0]
d5_8 = D12.iloc[4:8]; ratio = (d5_8.default_rate / d5_8.mean_pd)
top = D12.iloc[9]
lines = []
A = lines.append
A("# Модель PD покупателя: результаты обучения (версия 1.0)\n")
A("27.10.2026 · Руслан · Смарт-факторинг\n")
A(f"**Итог.** Модель обучена на когорте 2022 и проверена на когорте 2023, которая в настройке не участвовала. Gini на проверке {n(t12['gini'])} (доверительный интервал {n(t12['gini_ci95'][0])}–{n(t12['gini_ci95'][1])}) при требовании не ниже 0,5 и цели 0,6; на сегменте выручки от 800 млн ₽ {n(t12['segment_800m']['gini'])}. Уровни риска A–D по доле дефолтов растут монотонно, стабильность по PSI с большим запасом. Одно замечание по калибровке: на 2023 году фактическая доля дефолтов в средних децилях выше прогноза в {n(ratio.min(),1)}–{n(ratio.max(),1)} раза, а в верхнем ниже на {pc(1 - top.default_rate/top.mean_pd,0)} (подробности в разделе 3). Утечки по датам не найдено, но не проверяемо одно: дата подачи отчётности в витрине не хранится (раздел 5).\n")
A("## 1. Приёмка по ТЗ (когорта 2023, метка Б, окно 12 месяцев)\n")
A("| Критерий | Требование | Результат | Вывод |\n| --- | --- | --- | --- |")
A(f"| Gini | не ниже 0,5, цель 0,6, с доверительным интервалом | {n(t12['gini'],3)} ({n(t12['gini_ci95'][0],3)}–{n(t12['gini_ci95'][1],3)}) | выполнено |")
s8 = t12['segment_800m']
A(f"| Gini, выручка от 800 млн ₽ | то же, отдельно | {n(s8['gini'],3)} ({n(s8['gini_ci95'][0],3)}–{n(s8['gini_ci95'][1],3)}); {k(s8['n'])} компаний, {k(s8['defaults'])} дефолтов | выполнено |")
A(f"| Gini, окно 21 месяц | те же метрики отдельно | {n(t21['gini'],3)} ({n(t21['gini_ci95'][0],3)}–{n(t21['gini_ci95'][1],3)}); сегмент от 800 млн ₽ {n(t21['segment_800m']['gini'],3)} | выполнено |")
A(f"| Калибровка по децилям | средний PD близок к фактической доле дефолтов | средний PD {pc(t12['mean_pd'],2)} против факта {pc(t12['rate'],2)}; наибольший разрыв по децилям {n(t12['decile_max_abs_gap_pp'],1)} п.п. (верхний дециль) | выполнено с оговоркой, раздел 3 |")
A(f"| PSI | меньше 0,25 | скор {n(R['psi_score'],3)}; наибольший у признака {n(max(R['psi_features'].values()),3)} | выполнено |")
A(f"| Монотонность A–D | доля дефолтов растёт от A к D | {' / '.join(pc(x,1) for x in L12.default_rate)} | выполнено |")
A(f"| Утечка | данных после даты среза нет; Gini выше 0,9 — повод перепроверить | Gini {n(t12['gini'],2)}, максимум по одному признаку {n(au['max_single_feature_abs_gini'],2)}; даты подачи отчётности не проверяемы | выполнено с оговоркой, раздел 5 |\n")
A("## 2. Что обучали\n")
A(f"Выборка: когорта 2022 (отчётность за 2022 год, срез 01.04.2023), {k(tr['n'])} строк с определённой меткой, из них {k(tr['defaults'])} дефолтов ({pc(tr['rate'],2)}). Проверка: когорта 2023, {k(t12['n'])} строк, {k(t12['defaults'])} дефолтов ({pc(t12['rate'],2)}). Гейт 0 пройден: витрина воспроизводит списки ИНН один в один (182 584 и 210 511, расхождений нет). Фильтры из ТЗ: отчётность сдана, не выброс, без ОКВЭД K и O, выручка от 120 млн ₽.\n")
A("Признаки: 28 штук по разделу 6 ТЗ (13 коэффициентов, динамика за один и два года, флаги риска, масштаб, раздел ОКВЭД и регион), поля витрины с датами и событиями после среза в выборку не попали. Модель: LightGBM с весом дефолтного класса 5 и параметрами, выбранными кросс-валидацией по 2022 (5 частей, 14 вариантов). Калибровка Platt по предсказаниям вне обучающих частей; изотоническая дала почти такой же логлосс, но ступенчатый PD. Уровни A–D заданы по 2022: A < 0,4%, B 0,4–1,5%, C 1,5–6%, D ≥ 6%.\n")
A("## 3. Результаты на проверке 2023\n")
A("![](out/pd_plot_calibration_levels.png){width=17cm}\n")
A("![](out/pd_plot_shap.png){width=12cm}\n")
A("Доли дефолтов по уровням риска:\n")
A("| Уровень | Доля компаний | 2022, вне обучения | 2023, 12 мес. | 2023, 21 мес. |\n| --- | --- | --- | --- | --- |")
for i in range(4):
    A(f"| {L12.level[i]} | {pc(L12.share[i],0)} | {pc(LT.default_rate[i],2)} | {pc(L12.default_rate[i],2)} | {pc(L21.default_rate[i],2)} |")
A("")
A(f"**Калибровка.** Ранжирование на 2023 году стабильно, но уровень PD сдвигается: в децилях 5–8 фактическая доля дефолтов выше прогноза в {n(ratio.min(),1)}–{n(ratio.max(),1)} раза, в верхнем дециле прогноз {pc(top.mean_pd,1)} против факта {pc(top.default_rate,1)}. Общий средний PD {pc(t12['mean_pd'],2)} против {pc(t12['rate'],2)}. На окне 21 месяц фактическая доля естественно выше (в среднем {pc(t21['rate'],1)}), модель калибрована на 12 месяцев. Калибровку и границы уровней на 2023 не подгоняли, потому что это нарушило бы правило проверки.\n")
A("| Дециль | Средний PD | Факт | Дефолтов |\n| --- | --- | --- | --- |")
for _, r in D12.iterrows(): A(f"| {int(r.decile)} | {pc(r.mean_pd,2)} | {pc(r.default_rate,2)} | {k(r.defaults)} |")
A("")
A("## 4. Сравнение моделей и вариантов метки\n")
A("Кросс-валидация по 2022 (Gini вне обучающих частей) и проверка 2023:\n")
A("| Модель | Кросс-валидация 2022 | Проверка 2023, 12 мес. | Проверка 2023, 21 мес. |\n| --- | --- | --- | --- |")
for nm, r in (("Бустинг LightGBM (выбран)", lg), ("CatBoost", cb), ("Логистическая регрессия со сплайнами", lr_s), ("Логистическая регрессия линейная", lr_l)):
    A(f"| {nm} | {n(r.cv_gini_mean,3)} | {n(r.test12_gini,3)} | {n(r.test21_gini,3)} |")
A("")
A(f"Бустинг лучше линейной регрессии на {n(lg.cv_gini_mean-lr_l.cv_gini_mean,2)} в кросс-валидации (во всех пяти частях) и на {n(lg.test12_gini-lr_l.test12_gini,2)} на проверке. Регрессия со сплайнами ближе: бустинг лучше неё в среднем на {n(lg.cv_gini_mean-lr_s.cv_gini_mean,3)} в кросс-валидации (во всех пяти частях) и на {n(lg.test12_gini-lr_s.test12_gini,3)} на проверке, доверительные интервалы пересекаются. Бустинг оставлен: он впереди во всех пяти частях и на проверке, а SHAP даёт главные факторы по каждой компании. Разница со сплайновой регрессией при этом небольшая.\n")
A("Варианты метки (одна модель, одни признаки и части, кросс-валидация внутри 2022):\n")
A("| Обучено на | Оценка на «любой дефолт» (банкротство и исключение) | Оценка на «только банкротство» |\n| --- | --- | --- |")
nm = {"B": "Вариант Б: банкротство и исключение", "A": "Вариант А: только банкротство", "0": "Вариант 0: любая ликвидация"}
for v in ("B", "A", "0"):
    x = LV[LV.trained_on.astype(str) == v]
    gB = x[x.evaluated_against.str.startswith("target B")].gini.iloc[0]; gA = x[x.evaluated_against.str.startswith("target A")].gini.iloc[0]
    A(f"| {nm[v]} | {n(gB,3)} | {n(gA,3)} |")
A("")
A("Вариант Б лучше всех на «любом дефолте» и теряет около 0,03 на чистых банкротствах по сравнению с моделью, обученной только на банкротствах. Вариант 0 хуже по обеим целям: в нём реорганизации и добровольные ликвидации идут как дефолт. Выбор варианта Б по ТЗ подтверждается.\n")
A("## 5. Проверка на утечку\n")
A(f"Что проверено: поля витрины с событиями после среза убраны на этапе выборки (13 колонок); возраст считается как год отчётности минус год регистрации; лаги T−1 и T−2 у когорты 2023 совпадают со значениями когорты 2022 у всех {k(151144)} общих компаний по проверенным статьям (выручка, активы, капитал, прибыль, дебиторская задолженность); Gini ниже порога 0,9; без самого сильного признака (маржа) Gini {n(au['cv_gini_without_net_margin'],2)}, без маржи и абсолютной ликвидности {n(au['cv_gini_without_net_margin_and_cash_ratio'],2)}, без возраста и признака «нет отчётности за прошлый год» {n(au['cv_gini_without_age_and_no_prev_report'],2)}; по кварталам окна Gini {n(au['gini_2023_default_quarter_1']['gini'],2)} / {n(au['gini_2023_default_quarter_2']['gini'],2)} / {n(au['gini_2023_default_quarter_3']['gini'],2)} / {n(au['gini_2023_default_quarter_4']['gini'],2)} (убывает по мере удаления от среза).\n")
A(f"По типу дефолта: на банкротствах Gini {n(bt['2023_12m__банкротство']['gini'],2)} на проверке и {n(bt['2022_oof__банкротство']['gini'],2)} вне обучения; на исключениях из ЕГРЮЛ {n(bt['2023_12m__исключение']['gini'],2)} и {n(bt['2022_oof__исключение']['gini'],2)}. Исключения предсказываются легче: сильнее всего работает маржа около нуля при крупной выручке, типичная для компаний-транзитёров.\n")
A("**Что проверить нельзя.** Витрина не хранит дату подачи отчётности, поэтому не доказано, что отчётность года T была подана до 01.04 следующего года. Собственное поле витрины `pit_status` помечено как непроверенное. Если часть отчётов подана позже среза, качество на проверке могло быть завышено. Закрыть вопрос можно только датами подачи из первичного источника.\n")
A("## 6. Боевой скоринг и решения\n")
A(f"Для скоринга реальных покупателей подготовлена отчётность за 2024 год: {k(233667)} компаний по тем же фильтрам, из них {k(45685)} с выручкой от 800 млн ₽. Распределение на ней стабильно: PSI скора к обучению {n(V['psi_score_2024_vs_2022'],3)}, доли уровней A/B/C/D {pc(V['levels_share_2024']['A'],0)} / {pc(V['levels_share_2024']['B'],0)} / {pc(V['levels_share_2024']['C'],0)} / {pc(V['levels_share_2024']['D'],0)}. Функция `score(inn)` возвращает PD, уровень A–D и три фактора с направлением; для компании вне выборки (нет отчётности, выручка меньше 120 млн ₽, ОКВЭД K и O) возвращает статус `no_financials`, а не низкий риск. Когда будут выбраны ~1 200 покупателей, `score_many(список ИНН)` вернёт PD, уровень и три фактора по всем сразу.\n")
A("Два решения за тобой:\n")
A("1. Для скоринга покупателей берём отчётность за 2024 год (подготовлена) или другой год? Модель учили на отчётности за 2022 год; год 2024 для неё допустим, но на нём нет проверки по меткам.\n2. Переобучать ли модель на когортах 2022 и 2023 вместе перед боевым использованием? Так калибровка учтёт 2023 год и разрыв в децилях сократится, но независимой проверки после этого не будет, и метрики останутся из этого отчёта.\n")
A("## 7. Что в поставке\n")
A("| Файл | Что это |\n| --- | --- |\n| `pd_model.pkl` | модель: признаки, бустинг, калибровка, границы уровней |\n| `score_inn.py` | функция `score(inn)` и `score_many(список ИНН)` |\n| `scoring_store_2024.parquet` | данные для скоринга: отчётность за 2024 год |\n| `pd_company_year_features_2022.parquet`, `_2023.parquet`, `pd_fields.md` | таблица «компания-год» с признаками и метками, описание полей |\n| `pd_model_training_executed.ipynb` | ноутбук обучения с результатами |\n| `laptop_scripts/`, `0*_*.py`, `pd_*.py` | скрипты сборки выборки и обучения (версия RFSD `ca3665997c97…`) |\n| `out/` | таблицы и результаты: подбор параметров, сравнения, калибровка, проверки |\n")
open("pd_report.md", "w").write("\n".join(lines))
print("ok", len("\n".join(lines)))
